			    var vnRowIdx = vcGrdList.getEditRowIndex();
			    var voDsList = app.lookup("dsList");
			    
			    // row index의 Row객체를 반환합니다.
			    var voRow = voDsList.getRow(vnRowIdx);
			    
			    // 현재 row의 "fileIndex" 속성값을 반환합니다.
			    var vnFileIndex = voRow.getAttr("fileIndex");
			    if (vnFileIndex == null) {
			        
			        // fileIndex 값을 설정합니다.
			        vnFileIndex = newFileIndex();
			        
			        // "fileIndex"의 속성을 fileIndex 값으로 설정합니다.
			        voRow.setAttr("fileIndex", vnFileIndex);
			    }
			    
			    var vsFileInfo = voFileObj.name + "(" + (voFileObj.size / 1000).toFixed(2) + "KB)";
			    util.DataSet.setValue(app, "dsList", vnRowIdx, "column5", vsFileInfo);
			    
			    // 전역변수 fileStorage에 선택된 file 객체를  저장합니다.
