			    var selectState = cpr.data.tabledata.RowState.UPDATED | cpr.data.tabledata.RowState.INSERTED;
			    
			    // 신규, 수정 상태 값을 갖는 row를 검색하여 row index 배열을 반환합니다.
			    var vaRowIdxs = voDsList.getRowStatedIndices(selectState);
			    
			    vaRowIdxs.forEach(function(rowIndex) {
			        
			        // rowIndex에 해당하는 row index의 객체를 반환합니다.
			        var voRow = voDsList.getRow(rowIndex);
			        
			        // fileIndex에 해당하는 파일 객체입니다.
			        var vnFileIndex = voRow.getAttr("fileIndex");
			        if (vnFileIndex != null) {
			            
			            // 컬럼명 "column1" 해당하는 값을 반환합니다.
			            var column1 = voRow.getValue("column1");
			            
			            // fileIndex에 해당하는 파일 객체입니다.
			            var file = moFileStorage[vnFileIndex];
			            if (file != null) {
			                // 전송 시 추가로 전달되는 파라미터에 파일을 추가합니다.
			                vcSubSave.addFileParameter("f@" + column1, file);
			            }
			        }
			    });
			    
